CREATE TABLE conversation_session (id BIGINT NOT NULL AUTO_INCREMENT,session_key VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,user_id BIGINT NULL,title VARCHAR(255) NULL,metadata JSON NOT NULL DEFAULT (JSON_OBJECT()),summary_text MEDIUMTEXT NULL,summary_through_message_id BIGINT NULL,summary_prompt_version VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL,summary_updated_at DATETIME(6) NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(id),CONSTRAINT uk_conversation_session_key UNIQUE(session_key),KEY idx_conversation_session_user(user_id),KEY idx_conversation_session_summary_message(summary_through_message_id),CONSTRAINT ck_conversation_summary_prompt CHECK(summary_prompt_version IS NULL OR REGEXP_LIKE(summary_prompt_version,'^[A-Za-z0-9][A-Za-z0-9._:-]{0,63}$','c')),CONSTRAINT fk_conversation_session_user FOREIGN KEY(user_id) REFERENCES user_account(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
